bool isNumericKey(String key) {
  for (int i = 0; i < key.length; i++) {
    if (!RegExp(r'\d').hasMatch(key[i])) {
      return false; // 如果包含非数字字符，返回 false
    }
  }
  return true; // 全部都是数字
}

getOtherGameName(String key, String id) {
  String name = '';
  if (Helperothersgame[key] != null) {
    var newName = isNumericKey(id)
        ? Helperothersgame[key][int.parse(id)]
        : Helperothersgame[key][id];

    if (newName == null) {
      return id;
    }
    return newName;
  }
  return name;
}
